```sql
/* Подсчёт уникальных счетов с отрицательным балансом после снятия наличных по кредитной карте (VYBER KARTOU) */
/* для счетов с ежемесячной выдачей (POPLATEK MESICNE) */
SELECT COUNT(DISTINCT t."account_id") AS negative_balance_accounts
FROM "trans" t
JOIN "account" a ON a."account_id" = t."account_id"
WHERE t."operation" = 'VYBER KARTOU'
  AND t."balance" < 0
  AND a."frequency" = 'POPLATEK MESICNE';
```

```sql
/* Подсчёт общего числа атомов в молекулах, содержащих тройную связь и атомы фосфора или брома */
SELECT COUNT(DISTINCT a."atom_id") AS total_atoms
FROM "atom" a
JOIN "molecule" m ON a."molecule_id" = m."molecule_id"
WHERE a."element" IN ('p', 'br')
  AND m."molecule_id" IN (
      /* Молекулы, содержащие тройную связь */
      SELECT b."molecule_id"
      FROM "bond" b
      WHERE b."bond_type" = '#'
  );
```

```sql
/* Выбираем молекулы, у которых есть одинарные связи (bond_type = '-') */
/* и которые не являются канцерогенными (label = '-') */
/* Возвращаем топ-3 уникальных molecule_id в алфавитном порядке */
SELECT DISTINCT m."molecule_id"
FROM "molecule" m
JOIN "bond" b ON m."molecule_id" = b."molecule_id"
WHERE m."label" = '-'
  AND b."bond_type" = '-'
ORDER BY m."molecule_id"
LIMIT 3;
```

```sql
/* Выбираем молекулы, не являющиеся канцерогенными (label = '-'), */
/* у которых количество атомов больше 5 */
SELECT m."molecule_id", m."label"
FROM "molecule" m
JOIN "atom" a ON a."molecule_id" = m."molecule_id"
WHERE m."label" = '-'
GROUP BY m."molecule_id", m."label"
HAVING COUNT(a."atom_id") > 5;
```

```sql
/* Вычисляем процент молекул, содержащих водород (element = 'h'), среди канцерогенных молекул (label = '+') */
SELECT
    /* Процент = (число канцерогенных молекул с водородом) / (общее число канцерогенных молекул) * 100 */
    (COUNT(DISTINCT CASE WHEN a."element" = 'h' THEN m."molecule_id" END)::numeric
     / NULLIF(COUNT(DISTINCT m."molecule_id"), 0)) * 100.0 AS percentage
FROM "molecule" m
/* Присоединяем атомы молекулы */
LEFT JOIN "atom" a
    ON a."molecule_id" = m."molecule_id"
/* Ограничиваем только канцерогенными молекулами */
WHERE m."label" = '+';
```

```sql
/* Процент японских переводов среди наборов типа expansion */
SELECT
    /* Доля наборов типа expansion среди японских переводов, в процентах */
    (COUNT(DISTINCT CASE WHEN s."type" = 'expansion' THEN st."setcode" END)::numeric
     / NULLIF(COUNT(DISTINCT st."setcode"), 0)) * 100 AS percentage
FROM set_translations st
JOIN sets s ON s."code" = st."setcode"
WHERE st."language" = 'Japanese';
```

```sql
/* Доля карт без силы (power IS NULL или '*'), которые имеют французский язык */
SELECT
    /* Процент: французские карты без силы / все карты без силы * 100 */
    (COUNT(*) FILTER (WHERE fd."language" = 'French')::numeric
     / NULLIF(COUNT(*), 0)::numeric) * 100 AS percentage
FROM foreign_data fd
WHERE fd."power" IS NULL OR fd."power" = '*';
```

