/* Вычисляем отношение количества супергероев мужского пола к женскому */
SELECT
    /* Количество мужских супергероев */
    SUM(CASE WHEN g."gender" = 'Male' THEN 1 ELSE 0 END)::numeric
    /
    /* Количество женских супергероев */
    NULLIF(SUM(CASE WHEN g."gender" = 'Female' THEN 1 ELSE 0 END), 0) AS ratio
FROM "superhero" s
JOIN "gender" g ON s."gender_id" = g."id";

```sql
/* Доля героев Marvel Comics среди супергероев ростом 150-180 см */
SELECT
    /* Процент = (число героев Marvel / общее число героев в диапазоне) * 100 */
    SUM(CASE WHEN p."publisher_name" = 'Marvel Comics' THEN 1 ELSE 0 END)::numeric
    / COUNT(p."id") * 100 AS marvel_percentage
FROM "superhero" s
JOIN "publisher" p ON s."publisher_id" = p."id"
WHERE s."height_cm" BETWEEN 150 AND 180;
```

