/* Superheroes with missing weight data: weight_kg = 0 OR weight_kg IS NULL */
/* Count those with blue eyes (colour.id = 7) and those with no eye colour (colour.id = 1) */
/* Return the difference between the two counts */
SELECT
    SUM(CASE WHEN c.id = 7 THEN 1 ELSE 0 END)
    - SUM(CASE WHEN c.id = 1 THEN 1 ELSE 0 END) AS difference
FROM "superhero" s
LEFT JOIN "colour" c ON s."eye_colour_id" = c."id"
WHERE s."weight_kg" = 0 OR s."weight_kg" IS NULL;
```

